"""Mock Purplefish API Server for testing and development"""

import json
import threading
import time
from typing import Any
from typing import Dict
from typing import Optional

from pytest_httpserver import HTTPServer
from werkzeug import Response


class MockPurplefishServer:
    """Mock server for Purplefish API endpoints used in testing and development"""

    def __init__(
        self,
        httpserver: Optional[HTTPServer] = None,
        host: str = "127.0.0.1",
        port: int = 8000,
    ):
        """Initialize mock server

        Args:
            httpserver: Optional pytest HTTPServer for testing
            host: Host to bind to (for standalone mode)
            port: Port to bind to (for standalone mode)
        """
        self.server = httpserver
        self.host = host if not httpserver else httpserver.host
        self.port = port if not httpserver else httpserver.port
        self.engagement_counter = 1000
        self.engagements: Dict[str, Dict[str, Any]] = {}
        self.thread: Optional[threading.Thread] = None

        if httpserver:
            self.setup_routes()

    def setup_routes(self) -> None:
        """Define all Purplefish API mock endpoints"""
        if not self.server:
            return

        # Clear any existing handlers
        self.server.clear()

        # Create engagement endpoint - use a generic handler
        self.server.expect_request(
            "/api/engagements", method="POST"
        ).respond_with_handler(self._handle_create_engagement)

        # Health check endpoint
        self.server.expect_request("/health").respond_with_json(
            {"status": "ok", "service": "mock-purplefish-api"}
        )

    def setup_agent_config_route(
        self, engagement_id: str, config: Dict[str, Any]
    ) -> None:
        """Setup route for getting agent config"""
        if not self.server:
            return
        self.server.expect_request(
            f"/api/engagements/{engagement_id}/agent-config", method="GET"
        ).respond_with_json(config)

    def setup_data_point_route(self, engagement_id: str) -> None:
        """Setup route for posting data points"""
        if not self.server:
            return
        self.server.expect_request(
            f"/api/engagements/{engagement_id}/candidate-data-points", method="POST"
        ).respond_with_json({"success": True})

    def setup_message_route(self, engagement_id: str) -> None:
        """Setup route for posting messages"""
        if not self.server:
            return
        self.server.expect_request(
            f"/api/engagements/{engagement_id}/messages", method="POST"
        ).respond_with_json({"success": True})

    def _handle_create_engagement(self, request) -> Response:
        """Handle POST /api/engagements - Create engagement"""
        try:
            data = json.loads(request.data)
            room_name = data.get("roomName")
            opportunity_id = data.get("opportunityId")
            candidate_phone = data.get("candidatePhoneNumber")
            agent_phone = data.get("agentPhoneNumber")

            # Generate engagement ID
            engagement_id = f"eng_{self.engagement_counter}"
            self.engagement_counter += 1

            # Determine agent based on input
            if opportunity_id and opportunity_id.startswith("test_"):
                # For testing, use opportunity_id to determine agent type
                if "routing" in opportunity_id:
                    agent_name = "routing_agent"
                else:
                    agent_name = "screening_agent"
            else:
                # Default agent selection logic
                agent_name = "screening_agent"

            # Store engagement data
            self.engagements[engagement_id] = {
                "id": engagement_id,
                "roomName": room_name,
                "opportunityId": opportunity_id,
                "candidatePhoneNumber": candidate_phone,
                "agentPhoneNumber": agent_phone,
                "agentName": agent_name,
                "messages": [],
                "dataPoints": [],
            }

            # Setup additional routes for this engagement
            self.setup_agent_config_route(engagement_id, self._get_default_config())
            self.setup_data_point_route(engagement_id)
            self.setup_message_route(engagement_id)

            # Return response in camelCase (as real API does)
            return Response(
                json.dumps({"engagementId": engagement_id, "agentName": agent_name}),
                status=200,
                headers={"Content-Type": "application/json"},
            )
        except Exception as e:
            return Response(
                json.dumps({"error": str(e)}),
                status=400,
                headers={"Content-Type": "application/json"},
            )

    def _get_default_config(self) -> Dict[str, Any]:
        """Get default agent config"""
        return {
            "id": "mock_script_001",
            "callScriptSchemaVersion": "1.0",
            "callScriptVersion": "1.0",
            "candidateDataPointSchemas": {
                "issue_type": {
                    "key": "issue_type",
                    "description": "Type of technical issue",
                    "outputSchema": {
                        "type": "string",
                        "description": "Type of technical issue",
                    },
                }
            },
            "context": {
                "job": {
                    "title": "Mock Position",
                    "description": "Mock job description",
                    "company": "Mock Company",
                }
            },
            "tasks": [
                {
                    "id": "greeter_task",
                    "type": "greeter",
                    "configuration": {
                        "companyName": "Mock Company",
                        "introduction": "Hello! This is a test call.",
                    },
                },
                {
                    "id": "closer_task",
                    "type": "closer",
                    "configuration": {"closingMessage": "Thank you for your time!"},
                },
            ],
        }

    def reset(self) -> None:
        """Reset server state (useful between tests)"""
        self.engagement_counter = 1000
        self.engagements = {}
        if self.server:
            self.setup_routes()

    def start(self) -> Optional[HTTPServer]:
        """Start the server in standalone mode"""
        if self.server:
            # Already have a server (test mode)
            return self.server

        # Create standalone server
        from pytest_httpserver import HTTPServer

        self.server = HTTPServer(host=self.host, port=self.port)
        self.setup_routes()

        def run_server():
            if self.server:
                self.server.start()

        self.thread = threading.Thread(target=run_server)
        self.thread.daemon = True
        self.thread.start()

        # Wait for server to be ready
        time.sleep(0.5)
        return self.server

    def stop(self) -> None:
        """Stop the server"""
        if self.server:
            self.server.stop()
            self.server = None

    def get_url(self, path: str = "") -> str:
        """Get full URL for a path"""
        return f"http://{self.host}:{self.port}{path}"

